mixedreset arrayobjectarray
reset ले array को आन्तरिक pointer लाई पहिलो element मा rewind गर्दछ र पहिलो array element को value return गर्दछ।

  &reftitle.returnvalues;

पहिलो array element को value return गर्दछ, वा यदि array खाली छ भने &false; return गर्दछ।
  &return.falseproblem;

  &reftitle.examples;



    reset को उदाहरण


<?php

$array = array('step one', 'step two', 'step three', 'step four');

// by default, the pointer is on the first element
echo current($array) . "<br />\n"; // "step one"

// skip two steps
next($array);
next($array);
echo current($array) . "<br />\n"; // "step three"

// reset pointer, start again on step one
reset($array);
echo current($array) . "<br />\n"; // "step one"

?>
